import { vi } from 'vitest';

// required for svelte5 + jsdom as jsdom does not support matchMedia
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  enumerable: true,
  value: vi.fn().mockImplementation(query => ({
    matches: false,
    media: query,
    onchange: null,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  })),
});

// add more mocks here if you need them

import { cleanup, render } from '@testing-library/react';
import { SWRConfig } from 'swr';
import { beforeEach, afterEach, vi } from 'vitest';

export const setupTestComponent = (
  TestComponent: React.ComponentType<any>,
  {
    init,
  }: {
    init?: (TestComponent: React.ComponentType<any>) => React.ReactNode;
  } = {},
) => {
  beforeEach(() => {
    // reset SWR cache to isolate tests:
    render(
      <SWRConfig value={{ provider: () => new Map() }}>
        {init?.(TestComponent) ?? <TestComponent />}
      </SWRConfig>,
    );
  });

  afterEach(() => {
    vi.restoreAllMocks();
    cleanup();
  });
};

import { cleanup, render } from '@testing-library/vue';
import { beforeEach, afterEach, vi } from 'vitest';

export const setupTestComponent = (
  TestComponent: any,
  {
    init,
  }: {
    init?: (TestComponent: any) => any;
  } = {},
) => {
  beforeEach(() => {
    render(init?.(TestComponent) ?? TestComponent);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    cleanup();
  });

  return TestComponent;
};
